def inspect_lag(mapping):
    if 'lag' not in mapping:
        return {'accepted': False, 'lag': None}
    value = mapping['lag']
    if type(value) is bool or not type(value) is int or not -1 <= value <= 8:
        return {'accepted': False, 'lag': None}
